class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('Capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFunc = now;

    this.tokens = capacity;
    this.lastRefillTime = this.nowFunc();
  }

  _refill() {
    const currentTime = this.nowFunc();
    if (currentTime > this.lastRefillTime) {
      const elapsedSeconds = (currentTime - this.lastRefillTime) / 1000;
      const refillAmount = elapsedSeconds * this.refillPerSecond;
      this.tokens = Math.min(this.capacity, this.tokens + refillAmount);
      this.lastRefillTime = currentTime;
    } else if (currentTime < this.lastRefillTime) {
        // Saat geri giderse hiçbir şey yapma, sadece zamanı güncelleme 
        // (veya mevcut durumu koru). İstek: "en büyük zaman referansı kalır".
        // Bu durumda lastRefillTime'ı değiştirmemek en mantıklısı.
    }
  }

  tryTake(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._refill();

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this.tokens;
  }

  msUntil(n = 1) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._refill();

    if (this.tokens >= n) {
      return 0;
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity;
    }

    const needed = n - this.tokens;
    const msNeeded = (needed / this.refillPerSecond) * 1000;
    return Math.ceil(msNeeded);
  }
}

module.exports = { TokenBucket };

const { TokenBucket } = require('./kova');
const assert = require('assert');

function test() {
  console.log("Running tests...");

  // 1. Temel Testler
  let currentTime = 1000;
  const getTime = () => currentTime;

  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: getTime });
  assert.strictEqual(bucket.available(), 10, "Başlangıçta kova dolu olmalı");

  currentTime += 1000; // 1 saniye geçti, 2 jeton gelmeli (ama zaten doluydu)
  assert.strictEqual(bucket.available(), 10, "Kova kapasiteyi aşmamalı");

  bucket.tryTake(5);
  assert.strictEqual(bucket.available(), 5, "5 jeton alındıktan sonra 5 kalmalı");

  currentTime += 250; // 0.25 saniye geçti, 0.25 * 2 = 0.5 jeton gelmeli
  assert.strictEqual(bucket.available(), 5.5, "Zamanla kesirli dolum olmalı");

  // 2. msUntil Testleri
  currentTime += 100; // Toplam geçen: 350ms + 100ms = 450ms -> 0.45 * 2 = 0.9 jeton gelmeli. Mevcut: 5.5 + 0.9 = 6.4
  assert.strictEqual(bucket.available(), 6.4, "Zamanla dolum doğrulanmalı"); // Not: hassasiyet sorunları olabilir ama burada tam sayı/basit kesir kullanıyoruz

  // Yeniden başlat (temiz test için)
  currentTime = 1000;
  const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 5, now: getTime });
  assert.strictEqual(bucket2.msUntil(1), 0, "Yeterli jeton varsa msUntil 0 olmalı");

  currentTime += 1000; // 1 saniye geçti -> 5 jeton doldu (kapasite 10 idi, zaten doluydu)
  // Mevcut durum: capacity=10, refill=5. tryTake(7) yapalım.
  bucket2.tryTake(7); // Kalan 3
  currentTime += 1000; // 1 saniye geçti -> 5 jeton geldi. Toplam 8.
  assert.strictEqual(bucket2.available(), 8, "Dolum kontrolü");

  // msUntil için n=10 lazım. Mevcut 8. Kalan 2. Hız: 5/sn. 2 / 5 = 0.4 sn = 400ms.
  assert.strictEqual(bucket2.msUntil(10), 400, "msUntil doğru hesaplanmalı");

  // 3. Saat Geri Gitme Testi
  currentTime = 5000;
  const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: getTime });
  bucket3.tryTake(5); // Kalan 5
  currentTime = 4000; // Saat geri gitti!
  bucket3._refill(); // Manuel tetikleme (internal method kontrolü için)
  assert.strictEqual(bucket3.available(), 5, "Saat geri giderse jeton azalmamalı/artmamalı");

  // 4. Hata Durumları
  assert.throws(() => new TokenBucket({ capacity: -1, refillPerSecond: 1 }), RangeError);
  assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: -1 }), RangeError);
  assert.throws(() => bucket2.tryTake(-1), RangeError);
  assert.throws(() => bucket2.msUntil(0), RangeError);

  // 5. Infinity Durumu
  const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now: getTime });
  bucket4.tryTake(5); // Kalan 5
  assert.strictEqual(bucket4.msUntil(6), Infinity, "Dolum hızı 0 ise ve yetmiyorsa Infinity");

  const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: getTime });
  assert.strictEqual(bucket5.msUntil(11), Infinity, "n > capacity ise Infinity");

  console.log("Tüm testler başarıyla geçti!");
}

